import { createClient, EntryCollection } from 'contentful';

interface BlogPostFields {
  title: string;
  slug: string;
  body: string;
  publishedAt: string;
  author: {
    fields: {
      name: string;
    };
  };
}

const client = createClient({
  space: process.env.CONTENTFUL_SPACE_ID!,
  environment: process.env.CONTENTFUL_ENVIRONMENT_ID ?? 'master',
  accessToken: process.env.CONTENTFUL_DELIVERY_TOKEN!,
});

async function getBlogPosts(limit = 10) {
  const entries: EntryCollection<BlogPostFields> = await client.getEntries<BlogPostFields>({
    content_type: 'blogPost',
    order: ['-fields.publishedAt'],
    limit,
    include: 2, // resolve linked entries up to 2 levels deep
  });

  return entries.items.map((entry) => ({
    id: entry.sys.id,
    title: entry.fields.title,
    slug: entry.fields.slug,
    body: entry.fields.body,
    publishedAt: entry.fields.publishedAt,
    authorName: entry.fields.author?.fields?.name ?? 'Unknown',
  }));
}

const posts = await getBlogPosts(10);
console.log('Blog posts:', posts);

import { createClient } from 'contentful';

interface PageFields {
  title: string;
  slug: string;
  hero: {
    fields: {
      title: string;
      file: {
        url: string;
        details: { size: number; image: { width: number; height: number } };
      };
    };
  };
  body: unknown; // Rich Text — use @contentful/rich-text-html-renderer to render
}

const client = createClient({
  space: process.env.CONTENTFUL_SPACE_ID!,
  environment: process.env.CONTENTFUL_ENVIRONMENT_ID ?? 'master',
  accessToken: process.env.CONTENTFUL_DELIVERY_TOKEN!,
});

async function getPageById(entryId: string) {
  const entry = await client.getEntry<PageFields>(entryId, {
    include: 2,
  });

  return {
    id: entry.sys.id,
    title: entry.fields.title,
    slug: entry.fields.slug,
    heroImageUrl: entry.fields.hero?.fields?.file?.url
      ? `https:${entry.fields.hero.fields.file.url}`
      : null,
    body: entry.fields.body, // pass to documentToHtmlString() for rendering
  };
}

const page = await getPageById('5KsDBWseXY6QegucYAoacS');
console.log('Page:', page);
